NEW_FILES = {'migrations/migrate_aisle_markers.py': '#!/usr/bin/env python3\n"""\nmigrate_aisle_markers.py  --  a supermarket hangs a numbered marker over each aisle (0.276.0)\n=============================================================================================\nOne-shot, idempotent migration over specs/*.json. Furnish hangs a supermarket\'s aisle markers\n(`level_design.aisle_markers`) over the lanes between its gondolas, numbered from aisle 1, in Zoo 1.131.0\'s\n`aisle_sign` form `grocery`. The library is a fixed point of its furnishing pass, so every spec with a supermarket\'s\nsales floor is refurnished (`migrate_furnish_recipes.migrate`); no other spec is touched.\n\n`lf_*` specs are Level Factory\'s per-run transients and are skipped.\n\n    python migrations/migrate_aisle_markers.py            # write specs/\n    python migrations/migrate_aisle_markers.py --check    # report only; exit 1 if any would change\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\nsys.path.insert(0, os.path.join(HERE, "migrations"))\n\nimport level_design  # noqa: E402\nimport migrate_furnish_recipes  # noqa: E402\n\n\ndef _supermarket(d):\n    b = level_design.club_building_id(d)\n    return any(level_design.is_supermarket_floor(r, b) for r in d.get("rooms") or [])\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = os.path.join(HERE, "specs")\n    changed = 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not _supermarket(d):\n            continue\n        before = json.dumps(d, indent=1) + "\\n"\n        migrate_furnish_recipes.migrate(d)\n        after = json.dumps(d, indent=1) + "\\n"\n        if after == before:\n            continue\n        changed += 1\n        n = sum(1 for v in d["volumes"] if str(v.get("name", "")).startswith("aisle_sign_"))\n        print(f"[aisle_markers] {os.path.basename(p)}: {n} marker(s)")\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(after)\n    verb = "would change" if check else "refurnished"\n    print(f"[aisle_markers] {changed} spec(s) {verb}")\n    return 1 if check and changed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_aisle_markers.py': '"""A supermarket hangs a numbered marker over each aisle (0.276.0) -- pure, no bpy.\n\nThe walker\'s grocery comps, 2026-10-26 (the factory\'s docs/reference/GROCERY_STORE_COMPS.md): a printed sign over the\nhead of every aisle, its number large and what is down it beside it. Zoo 1.131.0\'s `aisle_sign` form `grocery`\nprints the number its variant gives; furnish hangs one over each lane between two lines of a supermarket\'s gondolas,\nat the lane\'s storefront end (`level_design.aisle_markers`).\n\nFAILS ON 0.275.0: `aisle_markers` does not exist and no supermarket hangs a marker.\n\nRun:  python -m pytest tests/test_aisle_markers.py\n"""\nimport json\nimport os\n\nimport agent_contract\nimport level_design as L\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nSHELLS = {"supermarket_a01": 4, "supermarket_a02": 3, "supermarket_a03": 3}\n\n\ndef _spec(stem):\n    return json.load(open(os.path.join(HERE, "specs", stem + ".json"), encoding="utf-8"))\n\n\ndef _floor(d):\n    return next(r for r in d["rooms"] if r["id"] == "sales_floor")\n\n\ndef _markers(d):\n    return [v for v in d["volumes"] if str(v["name"]).startswith("aisle_sign_")]\n\n\ndef test_a01s_markers_hang_over_its_four_lanes_at_the_storefront_end():\n    """Five 14 m aisles at x -14, -7, 0, 7, 14 (1.4 m deep) from y -11 to 3, the storefront glass on the south wall:\n    four lanes, a marker over each at x -10.5, -3.5, 3.5, 10.5, 0.6 m in from the aisles\' south end."""\n    d = _spec("supermarket_a01")\n    got = L.aisle_markers(d, _floor(d))\n    assert [(round(x, 2), round(y, 2)) for x, y, _sx, _sy in got] == [(-10.5, -10.4), (-3.5, -10.4), (3.5, -10.4),\n                                                                      (10.5, -10.4)]\n    assert all((sx, sy) == (1.4, 0.06) for _x, _y, sx, sy in got)\n\n\ndef test_every_supermarket_hangs_its_markers_numbered_in_order():\n    for stem, n in SHELLS.items():\n        d = _spec(stem)\n        ms = _markers(d)\n        assert len(ms) == n, (stem, [v["name"] for v in ms])\n        assert all(v.get("form") == "grocery" for v in ms), stem\n        assert sorted(int(v.get("variant", 0)) for v in ms) == list(range(n)), stem\n\n\ndef test_a_marker_hangs_over_a_lane_with_a_bodys_headroom_under_it():\n    sh_head = agent_contract.min_headroom()\n    for stem in SHELLS:\n        d = _spec(stem)\n        room = _floor(d)\n        floor = int(room.get("story", 0) or 0) * float(d.get("story_height", 3.5))\n        gondolas = [v for v in d["volumes"] if str(v["name"]).startswith("gondola_")]\n        for m in _markers(d):\n            assert m["z"] - m["size_z"] / 2.0 - floor >= sh_head - 1e-6, (stem, m["name"], m["z"])\n            for g in gondolas:\n                inside = (abs(m["x"] - g["x"]) < g["size_x"] / 2.0 and abs(m["y"] - g["y"]) < g["size_y"] / 2.0)\n                assert not inside, (stem, m["name"], g["name"])\n\n\ndef test_the_markers_reach_zoos_grocery_form():\n    import prop_species\n    assert prop_species.species_for_name("aisle_sign_r48016798_31") == "aisle_sign"\n    zoo = os.environ.get("DC_ZOO_ROOT") or os.path.join(HERE, "..", "zoo")\n    g = os.path.join(zoo, "zoo_keeper", "genome", "species", "aisle_sign.json")\n    if os.path.isfile(g):\n        genome = json.load(open(g, encoding="utf-8"))\n        assert "grocery" in genome["params"]["form"] and genome["module_variants"] >= max(SHELLS.values())\n'}
CHANGELOG = "## [0.276.0] - a supermarket hangs a numbered marker over each aisle\n\nThe walker's grocery comps, 2026-10-26 (the factory's docs/reference/GROCERY_STORE_COMPS.md) show a printed sign over\nthe head of every aisle, its number large and what is down it beside it. Zoo 1.131.0 prints one: `aisle_sign` form\n`grocery`, the number its variant gives.\n\n### Added\n- **`level_design.aisle_markers(spec, room)`**: where a supermarket's sales floor hangs its markers, aisle 1 first.\n  - Read off the gondolas on the room's floor, its own aisles or the rows furnish laid, grouped into lines along\n    the axis most of them are long in.\n  - Each lane between two neighbouring lines takes one marker, 0.6 m in from its storefront end: the end nearer the\n    storey's glazed wall, else the low end.\n  - The board is 1.4 m across the lane, or the lane's width less 10 cm; a lane under 0.5 m takes none. Twelve at most.\n- **Furnish hangs them last** in a supermarket's sales floor, `form: grocery`, the variant the aisle's index, and only\n  where the storey gives a body its headroom under one (`hung_headroom_ok`).\n- **`migrations/migrate_aisle_markers.py`** refurnishes the supermarkets: supermarket_a01 hangs 4, a02 3, a03 3.\n\n### Tests\n- `tests/test_aisle_markers.py` (2 of 4 fail on 0.275.0; the other two hold every marker there is, and on 0.275.0\n  there is none):\n  - supermarket_a01's four at its lanes' storefront end;\n  - every supermarket's markers numbered in order;\n  - each over a lane with a body's headroom under it;\n  - the markers reach Zoo's grocery form.\n\n"
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.275.0', 'Deli Counter 0.276.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
